    const ActivityQuestion(id: 'q2', title: 'Funcao quadratica', statement: 'Qual o valor de f(2)?', difficulty: ActivityQuestionDifficulty.easy, options: ['2', '4', '8'], correctOptionIndex: 1),
  ];
